export function cursorSettingsHtml(state,ui,tr,e){
 const status=ui.cursorStatus||{},busy=ui.cursorBusy?'disabled':'',enabled=state.capabilities.cursor;
 return `<div class="notice"><b>${tr('连接你自己的 Cursor','Connect your own Cursor')}</b><p>${tr('自动检测本机 CLI；未安装时可从官网安装，再完成官方网页登录。无需修改代码或重启服务。','Detect the local CLI, install it from Cursor if needed, then sign in on the official website. No code edits or server restart.')}</p></div>
 <div class="button-row cursor-actions"><button type="button" class="button secondary" data-action="cursor-connect" ${busy}>${tr('检测并连接','Detect and connect')}</button><button type="button" class="button secondary" data-action="cursor-install" ${busy}>${tr('安装连接工具','Install connector')}</button><button type="button" class="button secondary" data-action="cursor-login" ${busy}>${tr('Cursor 网页登录','Sign in to Cursor')}</button><button type="button" class="text-button" data-action="cursor-disable" ${busy} ${enabled?'':'disabled'}>${tr('断开本应用连接','Disconnect this app')}</button></div>
 <p id="cursor-status" class="field-help" role="status">${ui.cursorBusy?tr('正在处理，请稍候…','Working, please wait…'):e(status.message?tr(status.message):tr('点击检测并连接，检查本机 Cursor。','Click Detect and connect to check Cursor on this device.'))}</p>
 ${status.loginUrl?`<a class="button primary" href="${e(status.loginUrl)}" target="_blank" rel="noopener noreferrer">${tr('打开 Cursor 官方授权页','Open Cursor authorization')}</a><p class="field-help">${tr('请在官方页面登录并授权，完成后点击检查登录。','Sign in and authorize on the official page, then check the connection.')}</p>`:''}
 <button type="button" class="text-button" data-action="cursor-status" ${busy}>${tr('检查 Cursor 登录','Check Cursor sign-in')}</button>
 <details class="cursor-key"><summary>${tr('或使用自己的 Cursor API Key','Or use your own Cursor API key')}</summary><label>${tr('Cursor API Key','Cursor API key')}<input id="cursor-api-key" type="password" autocomplete="new-password" maxlength="2048"/></label><div class="button-row"><button type="button" class="button secondary" data-action="cursor-save-key">${tr('保存 Key','Save key')}</button><button type="button" class="text-button" data-action="cursor-clear-key">${tr('清除 Key','Clear key')}</button><a href="https://cursor.com/dashboard" target="_blank" rel="noopener noreferrer">${tr('Cursor 官方控制台','Cursor dashboard')}</a></div><p class="field-help">${tr('Key 仅保存在本次后端进程内存，仍需安装 CLI；网页登录信息由 Cursor 自行保存。','The key stays in server memory for this run and requires the CLI. Browser sign-in credentials are managed by Cursor.')}</p></details><input name="model" value="auto" type="hidden"/>`;
}
